use crate::aap::caps::state_read;

struct Node;

/// Keys tried in order. The first one that is present and yields at least
/// one URL wins.
const KEYS: &[&str] = &["urls", "subscriptions", "feeds"];

/// Parses a JSON array of strings, such as `["a", "b"]`.
/// Returns `None` if the text is not a well-formed array of strings.
fn parse_json_string_array(text: &str) -> Option<Vec<String>> {
    let mut chars = text.trim().chars().peekable();
    if chars.next()? != '[' {
        return None;
    }
    let mut out = Vec::new();
    loop {
        while matches!(chars.peek(), Some(c) if c.is_whitespace()) {
            chars.next();
        }
        match chars.next()? {
            ']' => break,
            ',' => continue,
            '"' => {
                let mut s = String::new();
                loop {
                    match chars.next()? {
                        '"' => break,
                        '\\' => match chars.next()? {
                            '"' => s.push('"'),
                            '\\' => s.push('\\'),
                            '/' => s.push('/'),
                            'b' => s.push('\u{8}'),
                            'f' => s.push('\u{c}'),
                            'n' => s.push('\n'),
                            'r' => s.push('\r'),
                            't' => s.push('\t'),
                            'u' => {
                                let mut code = 0u32;
                                for _ in 0..4 {
                                    code = code * 16 + chars.next()?.to_digit(16)?;
                                }
                                s.push(char::from_u32(code).unwrap_or('\u{fffd}'));
                            }
                            _ => return None,
                        },
                        c => s.push(c),
                    }
                }
                out.push(s);
            }
            _ => return None,
        }
    }
    Some(out)
}

/// Turns a stored value into a list of URLs.
///
/// A JSON array of strings is read as such. Anything else is split on
/// newlines and commas, with `#` comments and blank entries skipped.
/// Duplicates are removed, keeping the first occurrence.
fn parse_urls(raw: &str) -> Vec<String> {
    let trimmed = raw.trim();
    let candidates: Vec<String> = if trimmed.starts_with('[') {
        match parse_json_string_array(trimmed) {
            Some(v) => v,
            None => split_plain(trimmed),
        }
    } else {
        split_plain(trimmed)
    };

    let mut out: Vec<String> = Vec::new();
    for c in candidates {
        let u = c.trim();
        if u.is_empty() || u.starts_with('#') {
            continue;
        }
        if !out.iter().any(|e| e == u) {
            out.push(u.to_string());
        }
    }
    out
}

fn split_plain(text: &str) -> Vec<String> {
    text.lines()
        .map(|line| match line.find('#') {
            Some(0) => "",
            _ => line,
        })
        .flat_map(|line| line.split(','))
        .map(|s| s.trim().to_string())
        .filter(|s| !s.is_empty())
        .collect()
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        for key in KEYS {
            if let Some(raw) = state_read::get(key) {
                let urls = parse_urls(&raw);
                if !urls.is_empty() {
                    return SubscriptionList { urls };
                }
            }
        }
        SubscriptionList { urls: Vec::new() }
    }
}

export!(Node);
